(function(){"use strict";var toggle =document.querySelector(".nav-toggle");var links =document.querySelector(".nav-links");var overlay =document.querySelector("#nav-overlay");var body =document.body;function closeMenu(){if(links)links.classList.remove("open");if(toggle)toggle.setAttribute("aria-expanded","false");body.classList.remove("menu-open");}function openMenu(){if(links)links.classList.add("open");if(toggle)toggle.setAttribute("aria-expanded","true");body.classList.add("menu-open");}if(toggle &&links){toggle.addEventListener("click",function(e){e.stopPropagation();var isOpen =links.classList.contains("open");if(isOpen){closeMenu();}else{openMenu();}});links.querySelectorAll("a").forEach(function(a){a.addEventListener("click",function(){closeMenu();});});if(overlay){overlay.addEventListener("click",function(){closeMenu();});}document.addEventListener("click",function(e){if(links.classList.contains("open")&&!links.contains(e.target)&&!toggle.contains(e.target)){closeMenu();}});document.addEventListener("keydown",function(e){if(e.key ==="Escape" &&links.classList.contains("open")){closeMenu();}});window.addEventListener("resize",function(){if(window.innerWidth >980 &&links.classList.contains("open")){closeMenu();}});}document.querySelectorAll(".faq-item").forEach(function(item){var btn =item.querySelector(".faq-q");if(!btn)return;btn.addEventListener("click",function(){var isOpen =item.getAttribute("data-open")==="true";item.setAttribute("data-open",isOpen ? "false" :"true");btn.setAttribute("aria-expanded",isOpen ? "false" :"true");});});var revealEls =document.querySelectorAll(".reveal");if("IntersectionObserver" in window &&revealEls.length){var io =new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("in");io.unobserve(entry.target);}});},{threshold:0.12});revealEls.forEach(function(el){io.observe(el);});}else{revealEls.forEach(function(el){el.classList.add("in");});}var navAnchors =document.querySelectorAll('.nav-links a[href^="#"]');var sections =document.querySelectorAll('section[id]');var backToTopBtn =document.querySelector(".back-to-top");function setActiveNavLink(id){if(!id)return;navAnchors.forEach(function(a){var href =a.getAttribute("href");if(href ==="#" +id){if(!a.classList.contains("active")){a.setAttribute("aria-current","page");a.classList.add("active");}}else{if(a.classList.contains("active")){a.removeAttribute("aria-current");a.classList.remove("active");}}});}if("IntersectionObserver" in window &&sections.length &&navAnchors.length){var spyObserver =new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){setActiveNavLink(entry.target.getAttribute("id"));}});},{rootMargin:"-20% 0px -65% 0px",threshold:0});sections.forEach(function(sec){spyObserver.observe(sec);});}if(backToTopBtn){var isBackToTopVisible =false;var isScrollTicking =false;window.addEventListener("scroll",function(){if(!isScrollTicking){isScrollTicking =true;requestAnimationFrame(function(){var scrollPos =window.scrollY ||window.pageYOffset ||0;var shouldBeVisible =scrollPos >400;if(shouldBeVisible !==isBackToTopVisible){isBackToTopVisible =shouldBeVisible;backToTopBtn.classList.toggle("visible",isBackToTopVisible);}isScrollTicking =false;});}},{passive:true});backToTopBtn.addEventListener("click",function(e){e.preventDefault();window.scrollTo({top:0,behavior:"smooth"});});}var sliderContainer =document.querySelector(".gallery-grid.mobile-slider");var prevBtn =document.querySelector(".slider-arrow.prev");var nextBtn =document.querySelector(".slider-arrow.next");var dots =document.querySelectorAll(".slider-dots .dot");if(sliderContainer){var cachedCardWidth =0;function getCardWidth(){if(cachedCardWidth >0)return cachedCardWidth;var card =sliderContainer.querySelector(".gallery-item");if(card){cachedCardWidth =card.offsetWidth +24;}return cachedCardWidth ||280;}window.addEventListener("resize",function(){cachedCardWidth =0;},{passive:true});if(prevBtn){prevBtn.addEventListener("click",function(){sliderContainer.scrollBy({left:-getCardWidth(),behavior:"smooth"});});}if(nextBtn){nextBtn.addEventListener("click",function(){sliderContainer.scrollBy({left:getCardWidth(),behavior:"smooth"});});}var isSliderTicking =false;function updateDots(){var width =getCardWidth();var scrollLeft =sliderContainer.scrollLeft;var activeIndex =Math.round(scrollLeft /width);dots.forEach(function(dot,idx){if(idx ===activeIndex){dot.classList.add("active");dot.setAttribute("aria-current","true");}else{dot.classList.remove("active");dot.removeAttribute("aria-current");}});isSliderTicking =false;}sliderContainer.addEventListener("scroll",function(){if(!isSliderTicking){isSliderTicking =true;requestAnimationFrame(updateDots);}},{passive:true});dots.forEach(function(dot){dot.addEventListener("click",function(){var index =parseInt(dot.getAttribute("data-index"),10);if(!isNaN(index)){sliderContainer.scrollTo({left:index *getCardWidth(),behavior:"smooth"});}});});}window.switchPortalTab =function(tabId){var contentItems =document.querySelectorAll(".portal-tab-content");var tabBtns =document.querySelectorAll(".portal-tab-nav .btn-tab");contentItems.forEach(function(item){if(item.id ===tabId){item.style.display ="block";item.setAttribute("aria-hidden","false");}else{item.style.display ="none";item.setAttribute("aria-hidden","true");}});tabBtns.forEach(function(btn){if(btn.getAttribute("data-tab")===tabId){btn.classList.add("active");btn.setAttribute("aria-selected","true");btn.setAttribute("tabindex","0");}else{btn.classList.remove("active");btn.setAttribute("aria-selected","false");btn.setAttribute("tabindex","-1");}});};})();